sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    var th = 'style="background-color:#eef1f5;color:#2b3440;padding:9px 12px;font-size:12px;text-align:left;border:1px solid #e0e6ed;"';
    var td = 'style="padding:9px 12px;font-size:13px;color:#1a1a1a;border:1px solid #e0e6ed;"';
    var gr = new GlideRecord('x_birl3_clm_p1_crm_site_draft');
    gr.addQuery('crm_gp_request', current.getUniqueValue());
    gr.orderBy('site_code');
    gr.query();
    template.print('<table width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;">');
    template.print('<tr><th ' + th + '>Site Code</th><th ' + th + '>Group Code</th><th ' + th + '>Zone Code</th><th ' + th + '>Segment</th><th ' + th + ' align="right">Requested Limit</th></tr>');
    while (gr.next()) {
        template.print('<tr><td ' + td + '>' + gr.getValue('site_code') + '</td><td ' + td + '>' + gr.getValue('group_code') +
            '</td><td ' + td + '>' + gr.getValue('zone_code') + '</td><td ' + td + '>' + gr.getValue('segment') +
            '</td><td ' + td + ' align="right">' + gr.getDisplayValue('desired_limit') + '</td></tr>');
    }
    template.print('</table>');
})(current, template, email, email_action, event);
